// Calculate lane positions based on player and direction
const getLanePosition = (direction: ArrowDirection, playerType: Player): [number, number, number] => {
  const baseX = playerType === 'player1' ? -3 : 3;
  let laneX = 0;

  switch (direction) {
    case 'left': laneX = -1.5; break;
    case 'down': laneX = -0.5; break;
    case 'up': laneX = 0.5; break;
    case 'right': laneX = 1.5; break;
  }

  // Arrows now start from bottom and move up
  return [baseX + laneX, 0, arrow.position[2]];
};

updateArrows: (deltaTime) => set((prev) => {
  const { settings } = prev;
  const updatedArrows = prev.arrows
    .map(arrow => ({
      ...arrow,
      position: [
        arrow.position[0],
        arrow.position[1],
        // Arrows move from bottom (negative Z) to top (positive Z)
        arrow.position[2] + (settings.scrollSpeed * deltaTime * 0.01)
      ] as [number, number, number]
    }))
    // Remove arrows that have passed the hit zone (positive Z beyond hit zone)
    .filter(arrow => arrow.position[2] < 3 && !arrow.hit && !arrow.missed);

  return { arrows: updatedArrows };
}),

// Game actions
startGame: (song, isMultiplayer) => {
  set((prev) => ({
    gameState: {
      ...prev.gameState,
      isPlaying: true,
      isPaused: false,
      currentTime: 0,
      currentSong: song,
      gameMode: isMultiplayer ? 'multiplayer' : 'story',
      score: { player1: 0, player2: 0 },
      combo: { player1: 0, player2: 0 },
      accuracy: { player1: 100, player2: 100 }
    },
    isMultiplayer,
    arrows: [],
    showStory: false
  }));

  // Start generating arrows
  get().generateArrows(song, isMultiplayer);
},

// Arrow management
addArrow: (arrow: Arrow) => void;
updateArrows: (deltaTime: number) => void;
removeArrow: (arrowId: string) => void;
generateArrows: (song: Song, isMultiplayer: boolean) => void;

removeArrow: (arrowId) => set((prev) => ({
  arrows: prev.arrows.filter(arrow => arrow.id !== arrowId)
})),

generateArrows: (song, isMultiplayer) => {
  const directions: Array<'left' | 'down' | 'up' | 'right'> = ['left', 'down', 'up', 'right'];
  const players: Array<'player1' | 'player2'> = isMultiplayer ? ['player1', 'player2'] : ['player1'];

  // Generate a simple pattern for demonstration
  const generatePattern = () => {
    const pattern: Arrow[] = [];
    const duration = song.duration || 30000; // 30 seconds default
    const beatInterval = (60 / (song.bpm || 120)) * 1000; // milliseconds per beat

    for (let time = 1000; time < duration; time += beatInterval) {
      players.forEach(player => {
        // Generate random arrows for each beat
        if (Math.random() > 0.3) { // 70% chance to generate an arrow
          const direction = directions[Math.floor(Math.random() * directions.length)];
          const arrow: Arrow = {
            id: `${player}-${time}-${direction}`,
            direction,
            time,
            lane: directions.indexOf(direction),
            player,
            position: [0, 0, -10], // Start from bottom (negative Z)
            speed: 1,
            hit: false,
            missed: false
          };
          pattern.push(arrow);
        }
      });
    }

    return pattern;
  };

  const arrows = generatePattern();
  set(prev => ({ ...prev, arrows }));

  // Start the arrow spawning timer
  const spawnArrows = () => {
    const { gameState } = get();
    if (!gameState.isPlaying) return;

    const currentTime = gameState.currentTime;
    const upcomingArrows = arrows.filter(arrow => 
      arrow.time <= currentTime + 3000 && // 3 seconds ahead
      arrow.time > currentTime &&
      !get().arrows.some(existingArrow => existingArrow.id === arrow.id)
    );

    upcomingArrows.forEach(arrow => {
      get().addArrow(arrow);
    });

    if (gameState.isPlaying) {
      setTimeout(spawnArrows, 100); // Check every 100ms
    }
  };

  setTimeout(spawnArrows, 100);
},

import React, { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { Plane, Text, Box } from '@react-three/drei';
import { useGameStore } from '../../store/gameStore';
import DancingCharacter from './DancingCharacter';
import * as THREE from 'three';

const GameStage: React.FC = () => {
  const stageRef = useRef<THREE.Group>(null);
  const backgroundRef = useRef<THREE.Mesh>(null);
  const { gameState, isMultiplayer } = useGameStore();

  // Animate the background
  useFrame((state) => {
    if (backgroundRef.current) {
      backgroundRef.current.rotation.z = Math.sin(state.clock.elapsedTime * 0.1) * 0.1;
    }

    if (stageRef.current) {
      // Subtle breathing effect for the entire stage
      stageRef.current.scale.setScalar(1 + Math.sin(state.clock.elapsedTime * 0.5) * 0.02);
    }
  });

{/* Hit Zone Indicators */}
<group position={[0, 0, 2]}>
  {/* Player 1 hit zones */}
  <group position={[-3, 0, 0]}>
    {[-1.5, -0.5, 0.5, 1.5].map((x, index) => (
      <Box
        key={`p1-${index}`}
        position={[x, 0, 0]}
        args={[0.8, 0.1, 0.8]}
      >
        <meshLambertMaterial 
          color="#FF6B6B"
          transparent
          opacity={0.3}
          emissive="#FF6B6B"
          emissiveIntensity={0.1}
        />
      </Box>
    ))}
  </group>

  {/* Player 2 hit zones */}
  <group position={[3, 0, 0]}>
    {[-1.5, -0.5, 0.5, 1.5].map((x, index) => (
      <Box
        key={`p2-${index}`}
        position={[x, 0, 0]}
        args={[0.8, 0.1, 0.8]}
      >
        <meshLambertMaterial 
          color="#4ECDC4"
          transparent
          opacity={0.3}
          emissive="#4ECDC4"
          emissiveIntensity={0.1}
        />
      </Box>
    ))}
  </group>
</group>

{/* Dancing Characters */}
<DancingCharacter
  player="player1"
  position={[-3, 0, 2.5]}
  isHit={false}
  currentBeat={Math.floor(gameState.currentTime / 500)} // Beat every 500ms
/>

{isMultiplayer && (
  <DancingCharacter
    player="player2"
    position={[3, 0, 2.5]}
    isHit={false}
    currentBeat={Math.floor(gameState.currentTime / 500)} // Beat every 500ms
  />
)}

